use genewars_runtime::{mule_zone_credit::*,blueprint::BlueprintRng};use std::io::{Read,Write};fn main(){let mut data=Vec::new();std::io::stdin().read_to_end(&mut data).unwrap();let mut output=Vec::new();for c in data.chunks_exact(1961){let context=CreditContext{frame:u32::from_le_bytes(c[1948..1952].try_into().unwrap()),participating_players:1,selected_player:0,approval_limit:u16::from_le_bytes(c[1952..1954].try_into().unwrap())};let mut rng=BlueprintRng{seed:u16::from_le_bytes(c[1954..1956].try_into().unwrap()),ring:c[1956],draw_count:u32::from_le_bytes(c[1957..1961].try_into().unwrap())};let plan=plan_one_mule(c[..19].try_into().unwrap(),c[19..1824].try_into().unwrap(),c[1824..1948].try_into().unwrap(),context).unwrap();let mut requests=Vec::new();let count=plan.continuations.len();for continuation in plan.continuations{match continuation{Continuation::Audio{creature_slot,code,ebx,ecx,stack}=>{requests.push(1);requests.extend(creature_slot.to_le_bytes());requests.extend([code,ebx,ecx]);for v in stack{requests.extend(v.to_le_bytes());}},Continuation::Marker{creature_slot,code,ebx,ecx,stack}=>{requests.push(2);requests.extend(creature_slot.to_le_bytes());requests.extend([code,ebx,ecx]);for v in stack{requests.extend(v.to_le_bytes());}},Continuation::ParticleTail(tail)=>{let p=plan_particle_tail(&tail,rng).unwrap();rng=p.rng_after;requests.extend([3,p.code,p.owner]);for v in p.position{requests.extend(v.to_le_bytes());}requests.extend(p.physical_height.to_le_bytes());for v in p.angles{requests.extend(v.to_le_bytes());}for v in p.stack{requests.extend(v.to_le_bytes());}}}}output.extend(plan.zone_after);output.extend(plan.player_after);output.extend(rng.seed.to_le_bytes());output.push(rng.ring);output.extend(rng.draw_count.to_le_bytes());output.push(count as u8);output.extend(requests);}std::io::stdout().write_all(&output).unwrap();}